/// The boot executable (`boot/SCUS_971.99`), read once per process.
pub fn boot_elf() -> Option<&'static [u8]> {
    static ELF: std::sync::OnceLock<Option<Vec<u8>>> = std::sync::OnceLock::new();
    ELF.get_or_init(|| {
        let root = crate::level_load::extracted_root();
        crate::disc_source::read_path(&root, &root.join("boot/SCUS_971.99")).map_err(|e| eprintln!("boot ELF not read ({e:#})")).ok()
