fn vr_body_parts(p: &Play) -> [Option<MobyId>; 3] {
    #[cfg(feature = "vr")]
    if crate::vr::game_requested() && p.svc.game_mode == 0 && matches!(p.game.hero.mode, 1..=3) {
        let b = &p.game.hero.bodies;
        return [b.moby, b.rotor, b.glow];
    }
    #[cfg(not(feature = "vr"))]
    let _ = p;
    [None; 3]
}

