/// (crate::travel_render's post-tick), past the statics' drive, which drew the hull one tick behind its riders (Ratchet,
/// Clank) and the view, a gap growing with its speed.
pub(crate) fn drive_ship(p: &Play, occl: &mut MobyOcclusion) {
    let Some((id, ii)) = p.ship else { return };
    let Some(m) = p.game.mobys.mobys.get(id) else { return };
    let hidden = m.state >= 0x80 || m.mode & 0x81 != 0 || m.alpha == 0;
    occl.drive(ii, pos3(m), rows3(&m.rows), m.scale, None, hidden);
}

