/// The blended phase's final order, one sort per view (the views in parallel): the tagged items first, in the
/// game's order (module doc, "Order"), then the others back to front as Bevy sorted them. Before batching, so
/// consecutive items of one mesh and material become one instanced draw.
///
/// Equal keys go by distance, then by main-world entity, for run-to-run identical frames: Bevy's stable sort runs
/// over a retained map whose order is the order items were first queued, i.e. the order their pipelines finished
/// compiling on the async task pool, and items at equal depth (every part entity of one tie / shrub / moby
/// instance shares its transform) would draw in a run-dependent order. The main-world entity index follows the
/// deterministic spawn order (per instance, its parts in class order). This was crate::determinism's own sort
/// before this one; one sort per view replaces the two.
fn order(mut phases: ResMut<ViewSortedRenderPhases<Transparent3d>>, set: Res<Tagged>) {
    let set = &set.0;
    let key = |k: &(Entity, MainEntity), item: &Transparent3d| {
        (set.get(&k.1).map_or((1, WorldDrawOrder::NONE), |o| (0, *o)), FloatOrd(item.distance), k.1)
    };
    let key = &key;
    ComputeTaskPool::get().scope(|scope| {
        for phase in phases.values_mut() {
            scope.spawn(async move { phase.items.sort_by_cached_key(|k, item| key(k, item)) });
        }
    });
}

