    /// Ship-local pilot frame from the animated ship root, including its streamed translation.
    #[cfg(feature = "vr")]
    pub(crate) fn pilot_view(&self, p: &Play) -> Option<(bevy::math::Vec3, bevy::math::Quat)> {
        use rc_game::travel::space::{Phase, SUB_TAKEOFF, SUB_LANDING, SUB_FLYAWAY};
        // Space loading retains its native external camera; only the planet-side voyage is embodied.
        use std::sync::atomic::Ordering::Relaxed;
        if self.mode.phase == Phase::Idle || !matches!(self.mode.sub, SUB_TAKEOFF | SUB_LANDING | SUB_FLYAWAY) {
            self.pilot_seated.store(false, Relaxed);
            return None;
        }
        if self.mode.sub != SUB_TAKEOFF { self.pilot_seated.store(false, Relaxed); }
        // Landing: until ticks(0x168), the cut out of the canopy-opening shot, the authored actor track sinks Ratchet
        // about 2.5 units under the pad (the game only turns his shadow on after it). Keep the native seat meanwhile.
        let in_cockpit = self.mode.sub == SUB_LANDING && self.mode.tick <= p.svc.ticks(0x168);
        let boarding=(matches!(self.mode.sub, SUB_TAKEOFF | SUB_LANDING) && !in_cockpit).then(||self.boarding_eye(p)).flatten();
        let pose = self.poses.iter().find(|a| (530..=533).contains(&a.class));
        let (position, axes) = if let Some(a) = pose {
            let anim = self.gfx.actors.get(a.actor)?;
            let (class, slot) = self.mode.actor_anim.get(a.actor).and_then(|a| a.as_ref())
                .map_or((&anim.anim, anim.slot), |a| (a.1.as_ref(), a.2));
            let state = AnimState { seq_a: slot, frame_a: a.frame_a, seq_b: slot, frame_b: a.frame_b, t: a.t, speed: 1.0, rate: 1.0, flags: 0, trigger_count: 0, skip_advance: true };
            let root = moby_anim::evaluate_chain(class, &state, None, &[0]);
            let local = root[3];
            let scale = a.scale.unwrap_or(anim.scale);
            let (c, s) = (a.yaw.cos(), a.yaw.sin());
            ([a.position[0] + (c * local[0] - s * local[1]) * scale / 1024.0,
              a.position[1] + (s * local[0] + c * local[1]) * scale / 1024.0,
              a.position[2] + local[2] * scale / 1024.0], {
                let yaw=bevy::math::Mat3::from_rotation_z(a.yaw);
                yaw*bevy::math::Mat3::from_cols_array_2d(&[root[0][..3].try_into().ok()?,root[1][..3].try_into().ok()?,root[2][..3].try_into().ok()?])
              })
        } else {
            let m = p.game.mobys.mobys.get(p.svc.travel.moby?)?;
            ([m.position[0], m.position[1], m.position[2]], bevy::math::Mat3::from_cols_array_2d(&[0,1,2].map(|i|m.rows[i][..3].try_into().unwrap())))
        };
        // Native Ratchet seat for each ship, plus his seated eye height.
        let mut offset = rc_game::travel::RIDER_RATCHET[rc_game::travel::ship_index(p.svc.travel.ship)];
        offset[2] += 1.45;
        // The starter green cockpit's eye sits forward of the rider's pelvis. Final purple ship is unchanged.
        if rc_game::travel::ship_index(p.svc.travel.ship)==0 {offset[0]+=0.65;}
        let eye = bevy::math::Vec3::from_array(position)+axes*bevy::math::Vec3::from_array(offset);
        let forward=crate::tfrag_render::game_to_bevy(axes.x_axis.normalize_or_zero().to_array());
        let up=crate::tfrag_render::game_to_bevy(axes.z_axis.normalize_or_zero().to_array());
        let rotation=bevy::prelude::Transform::IDENTITY.looking_to(forward,up).rotation;
        let seat = crate::tfrag_render::game_to_bevy(eye.to_array());
        if let Some((head, heading)) = boarding {
            let flying = forward.y.abs() > 0.08;
            let mut seated = ((1.5 - head.distance(seat)) / 0.55).clamp(0.0, 1.0);
            // Seated, the eye is the hull's seat (from the ship's pose and root joint the hull is drawn with): Ratchet's
            // own track is authored apart from the ship's and drifts out of it during the take-off.
            if self.mode.sub == SUB_TAKEOFF {
                if flying || seated >= 1.0 { self.pilot_seated.store(true, Relaxed); }
                if self.pilot_seated.load(Relaxed) { seated = 1.0; }
            }
            Some((head.lerp(seat, seated), heading.slerp(rotation, if flying { 1.0 } else { seated })))
        } else {
            Some((seat, rotation))
        }
    }

    /// Follow the actual Ratchet actor through boarding, sitting and climbing back out.
    #[cfg(feature = "vr")]
    fn boarding_eye(&self, p: &Play) -> Option<(bevy::math::Vec3, bevy::math::Quat)> {
        // Hidden boarding actors may be parked below the world between streamed keys.
        let pose = self.poses.iter().find(|a| a.class == 0 && !a.hidden)?;
        let gfx = self.gfx.actors.get(pose.actor)?;
        let (class, slot) = self.mode.actor_anim.get(pose.actor).and_then(|a| a.as_ref())
            .map_or((&gfx.anim, gfx.slot), |a| (a.1.as_ref(), a.2));
        if class.frame(slot, pose.frame_a).is_none()
            || (pose.t != 0.0 && class.frame(slot, pose.frame_b).is_none()) { return None; }
        let chain = p.game.item_data.as_ref()?.hero_chains.get(rc_game::hero::worn::HEAD_ATTACH)?;
        if chain.is_empty() { return None; }
        let actor = pose.moby.and_then(|id| p.game.mobys.mobys.get(id));
        let mods = actor.map_or(&[][..], |m| m.joint_mods.as_slice());
        let state = AnimState { seq_a: slot, frame_a: pose.frame_a, seq_b: slot, frame_b: pose.frame_b, t: pose.t, speed: 1.0, rate: 1.0, flags: 0, trigger_count: 0, skip_advance: true };
        let head = moby_anim::evaluate_chains_posed(class, &state, None, &[chain.as_slice()], &[], mods).into_iter().next()?[3];
        // Match the streamed actor's renderer, including its actual class scale.
        let scale = pose.scale.unwrap_or(gfx.scale) / 1024.0;
        let (c, s) = (pose.yaw.cos(), pose.yaw.sin());
        let eye = [pose.position[0] + (c * head[0] - s * head[1]) * scale,
                   pose.position[1] + (s * head[0] + c * head[1]) * scale,
                   pose.position[2] + head[2] * scale + 0.15];
        Some((crate::tfrag_render::game_to_bevy(eye), bevy::math::Quat::from_rotation_y(pose.yaw - std::f32::consts::FRAC_PI_2)))
    }

