/// Builds level `index`'s [`PreparedLevel`] (its four parts in parallel).
fn prepare_level(level: &crate::level_load::LoadedLevel, index: u32) -> PreparedLevel {
    let t0 = std::time::Instant::now();
    let timed = |f: &dyn Fn() -> PreparedPart| { let t = std::time::Instant::now(); (f(), t.elapsed()) };
    let parts = std::thread::scope(|s| {
        let jobs = [
            s.spawn(|| timed(&|| PreparedPart::Tfrags(crate::tfrag_render::prepare(level)))),
            s.spawn(|| timed(&|| PreparedPart::Ties(crate::tie_render::prepare(level)))),
            s.spawn(|| timed(&|| PreparedPart::Shrubs(crate::shrub_render::prepare(level)))),
            s.spawn(|| timed(&|| PreparedPart::Mobys(crate::moby_render::prepare(level, index)))),
        ];
        jobs.map(|j| j.join().map_err(|_| eprintln!("level switch: a level {index:02} preparation panicked; its level start builds it")).ok())
    });
    let mut p = PreparedLevel { index, ..Default::default() };
    let mut ms = [0.0f64; 4];
    for (i, (part, t)) in parts.into_iter().enumerate().filter_map(|(i, x)| x.map(|x| (i, x))) {
        ms[i] = t.as_secs_f64() * 1e3;
        match part {
            PreparedPart::Tfrags(x) => p.tfrags = Some(x),
            PreparedPart::Ties(x) => p.ties = Some(x),
            PreparedPart::Shrubs(x) => p.shrubs = Some(x),
            PreparedPart::Mobys(x) => p.mobys = Some(x),
        }
    }
    println!(
        "level switch: level {index:02} prepared beside the load in {:.1} ms (tfrags {:.1}, ties {:.1}, shrubs {:.1}, mobys {:.1})",
        t0.elapsed().as_secs_f64() * 1e3, ms[0], ms[1], ms[2], ms[3]
    );
    p
}

