    let mesh_handles: Vec<Handle<Mesh>> = p.meshes.into_iter().map(|m| stream.mesh(meshes, m)).collect();
    let inst_buffer = buffers.add(ShaderBuffer::new(&p.records, RenderAssetUsages::RENDER_WORLD));
    let lod_state = crate::tie_lod::TieLodState::new(p.lod_inputs, level.occlusion.objects.tie.clone(), level.fog, buffers);
    let lod_buffer = lod_state.buffer.clone();
    let image_handles: Vec<Handle<Image>> = p.images.into_iter().map(|i| stream.image(images, i)).collect();
    let material_handles = p
        .materials
        .iter()
        .map(|&(image, mxl, pass)| {
            materials.add(TieMaterial {
                texture: image_handles[image].clone(),
                fog: crate::game_camera::fog_buffer(),
                params: TieParams { misc: Vec4::new(crate::game_camera::NEAR, mxl as f32, p.tint, 0.0) },
                instances: inst_buffer.clone(),
                lods: lod_buffer.clone(),
                pass,
            })
        })
        .collect();
    let mut spawn = TieSpawn { meshes: mesh_handles, materials: material_handles, plan: p.plan, instances: p.instances, layer: layer.cloned(), next: 0 };
    commands.insert_resource(lod_state);
    if stream.deferring() {
        stream.job(Box::new(move |world, deadline| spawn.run(world, Some(deadline))));
    } else {
        commands.queue(move |world: &mut World| { spawn.run(world, None); });
    }
    let mut st = p.stats;
    st.spawn = t0.elapsed();
    st
}

/// The part entities of a [`TiePrepared`], spawned instance by instance.
struct TieSpawn {
    meshes: Vec<Handle<Mesh>>,
    materials: Vec<Handle<TieMaterial>>,
    plan: Vec<PartEntity>,
    instances: Vec<(u32, std::ops::Range<usize>)>,
    layer: Option<bevy::camera::visibility::RenderLayers>,
    /// The next instance to spawn.
    next: usize,
}

impl TieSpawn {
    /// Spawns the next instances' part entities and names them in the `TieLodState` until `deadline` (None: all);
    /// true when nothing is left (or the level's tie state is gone).
    fn run(&mut self, world: &mut World, deadline: Option<Instant>) -> bool {
        while self.next < self.instances.len() {
            if !world.contains_resource::<crate::tie_lod::TieLodState>() { return true; }
            let (ii, range) = self.instances[self.next].clone();
            let mut spawned = Vec::with_capacity(range.len());
            for pe in &mut self.plan[range] {
                let mut e = world.spawn((
                    Mesh3d(self.meshes[pe.mesh].clone()),
                    MeshMaterial3d(self.materials[pe.material].clone()),
                    pe.transform,
                    MeshTag(pe.tag),
                    WorldDrawOrder(pe.order),
                    Name::new(std::mem::take(&mut pe.name)),
                ));
                if pe.no_frustum { e.insert(NoFrustumCulling); }
                if let Some(l) = &self.layer { e.insert(l.clone()); }
                spawned.push(e.id());
            }
            world.resource_mut::<crate::tie_lod::TieLodState>().set_entities(ii as usize, spawned);
            self.next += 1;
            if self.next.is_multiple_of(16) && deadline.is_some_and(|d| Instant::now() >= d) { break; }
        }
        self.next >= self.instances.len()
    }
}

